INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شتو:khalil_kitab_ayn', 'شتو', '63bdfdd8073a10bb5647596056', 'الشِّتاء: معروف، والواحدة: شتوة. والموضعُ: المشتى والمشتاةُ، والفعلُ: شتا يشتو.', 'winter, well known; to spend winter', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_18234b9c4bbe35de', '2282', NULL, 'blk_kay_e884d23f3279b00c', 0, NULL, 'Marker: head gloss. Reading: winter.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شتو:ibn_durayd_jamharat_lugha', 'شتو', '63bdfdd8073a10bb5647596056', 'الشِّتاء مَمْدُود. والمَشْتَى: الْموضع الَّذِي تشتو فِيهِ.', 'winter; the place you spend winter', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_bba2a268773c7a27', '540', NULL, 'blk_jam_a02ca7bf77d41a1b', 0, NULL, 'Marker: head gloss. Reading: winter.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شتو:jawhari_sihah', 'شتو', '63bdfdd8073a10bb5647596056', 'وشَتَوْتُ بموضع كذا وتَشَتَّيْتُ: أقمت به الشِتا', 'I stayed the winter in a place', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_19e9aec1507f735b', '4737', 6, 'blk_sih_3ce8f26a67e4f027', 0, NULL, 'Marker: head gloss of the verb. Reading: spending winter. Primary: winter — 9 of 9 books (al-Khalīl blk_kay_e884d23f3279b00c; Ibn Durayd blk_jam_a02ca7bf77d41a1b; al-Jawharī blk_sih_3ce8f26a67e4f027; Ibn Fāris blk_mqy_594b93081b8fee30; al-Rāghib blk_mfr_125ebed3787e676c; Lisān blk_lsn_f4b87834f099ce9e; al-Miṣbāḥ blk_msb_adacf226454a08ef; Tāj blk_taj_34d65d3ab0b8500a; Lane blk_lane_37f174f34a13c1c7).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شتو:raghib_mufradat', 'شتو', '63bdfdd8073a10bb5647596056', 'يقال: شَتَّى وأَشْتَى، وصاف وأصاف، والْمَشْتَى والْمَشْتَاةَ للوقت، والموضع، والمصدر', 'spent winter; winter''s time and place', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_8aba1b03388d4d78', '445', 1, 'blk_mfr_125ebed3787e676c', 0, NULL, 'Marker: «يقال». Reading: winter.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شتو:ibn_manzur_lisan_arab', 'شتو', '63bdfdd8073a10bb5647596056', 'فبدؤوا بأَوَّل السَّنَةِ أَول الشِّتَاءِ لأَنه ذكَرٌ وَالصَّيْفُ أُنثى، ثُمَّ جَعَلُوا الشِّتَاءَ نِصْفَيْنِ', 'the year starts with winter, its first half', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_3d94ceda39893363', '7545', 14, 'blk_lsn_f4b87834f099ce9e', 0, NULL, 'Marker: first definition. Reading: winter. Quoted from Ibn al-Sikkīt via Lisān.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شتو:fayyumi_misbah_munir', 'شتو', '63bdfdd8073a10bb5647596056', 'الشِّتَاءُ قِيلَ جَمْعُ شَتْوَةٍ مِثْلُ: كَلْبَةٍ وَكِلَابٍ نَقَلَهُ ابْنُ فَارِسٍ عَنْ الْخَلِيلِ وَنَقَلَهُ بَعْضُهُمْ عَنْ الْفَرَّاءِ وَغَيْرِهِ وَيُقَالُ إنَّهُ مُفْرَدٌ عَلَمٌ عَلَى الْفَصْلِ', 'winter: the name of the season', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_f57ffee4a2af032e', '1545', NULL, 'blk_msb_adacf226454a08ef', 0, NULL, 'Marker: head gloss. Reading: winter.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شتو:zabidi_taj_arus', 'شتو', '63bdfdd8073a10bb5647596056', 'الشَّتاءُ، ككِساءٍ، ﴿والشَّاتاةُ) ، وَهَذِه عَن الصَّاغاني، (أَحَدُ أَرْباعِ الأَزْمِنَةِ)', 'winter: one of the four seasons', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_af6d7e3170eabe4f', '349', 38, 'blk_taj_34d65d3ab0b8500a', 0, NULL, 'Marker: Qāmūs gloss. Reading: winter.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شتو:lane_lexicon', 'شتو', '63bdfdd8073a10bb5647596056', 'The winter commenced', 'winter began', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_2b8f9516c690d5e4', '1503', NULL, 'blk_lane_37f174f34a13c1c7', 0, NULL, 'Marker: first sense A1. Reading: winter.', 'high', 'active');
