INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شجر:khalil_kitab_ayn', 'شجر', 'b2c8233eb84435d8ab3dcaa88e', 'وفَرقٌ ما بين الشجَر والبقل، أنَّ الشَّجَرَ يبقى له أرُومةٌ على الشتاء ولا يبقى للبقل شي', 'trees keep a stump through winter; herbs don''t', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_a27910b3d0b19ec3', '2034', NULL, 'blk_kay_0a87d92d21958038', 0, NULL, 'Marker: head gloss. Reading: tree.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شجر:ibn_durayd_jamharat_lugha', 'شجر', 'b2c8233eb84435d8ab3dcaa88e', 'وَالشَّجر: مَعْرُوف الْوَاحِدَة شَجَرَة. وَالْفرق بَين البقل وَالشَّجر أَن الشّجر يبْقى لَهُ سَاق', 'trees keep a trunk; herbs have none', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_8b8fd6513ba86aa2', '422', NULL, 'blk_jam_f51f981adb820708', 0, NULL, 'Marker: head gloss. Reading: tree.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شجر:jawhari_sihah', 'شجر', 'b2c8233eb84435d8ab3dcaa88e', 'الشَجَرُ والشَجَرَةُ: ما كان على ساقٍ من نبات الأرض.', 'plants that stand on a trunk', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_1e1c6f1d40d51b2a', '1373', 2, 'blk_sih_429336f5a89593ca', 0, NULL, 'Marker: head gloss. Reading: tree. Primary: tree — 7 of 9 books (al-Khalīl blk_kay_0a87d92d21958038; Ibn Durayd blk_jam_f51f981adb820708; al-Jawharī blk_sih_429336f5a89593ca; al-Rāghib blk_mfr_3a042f3baaeac080; Lisān blk_lsn_6e3325fcd2136304; al-Miṣbāḥ blk_msb_618ba52d3b54f82d; Tāj blk_taj_37d4dd99cf11665a). Other readings: interweaving: Ibn Fāris, Lane · rising high: Ibn Fāris.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شجر:raghib_mufradat', 'شجر', 'b2c8233eb84435d8ab3dcaa88e', 'الشَّجَرُ من النّبات: ما له ساق', 'plants that have a trunk', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_3c01bf9037b1b5cd', '446', 1, 'blk_mfr_3a042f3baaeac080', 0, NULL, 'Marker: opening definition. Reading: tree.', 'high', 'active');
