INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شجر:zabidi_taj_arus', 'شجر', 'b2c8233eb84435d8ab3dcaa88e', '(مِنَ النَّبَاتِ: مَا قَامَ على سَاقٍ) (أَو) هُوَ كُلّ (مَا سَمَا بِنَفْسِه، دَقَّ أَو جَلَّ', 'plants that stand on a trunk', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_eda21cba80c6f84d', '136', 12, 'blk_taj_37d4dd99cf11665a', 0, NULL, 'Marker: Qāmūs gloss. Reading: tree.', 'high', 'active');
