INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شرد:zabidi_taj_arus', 'شرد', 'f0a177774149a6c9ed9791ac3e', 'شرد: (شَرَدَ) البعيرُ والدَّابَّةُ يَشرُد شَرْداً، و (شُروداً) ، كقُعُود، (وشُرَاداً) ، كغُرَاب، (وشِرَاداً، بِالْكَسْرِ: نَفَرَ', 'the camel or beast bolted', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_fe371ac69c85c6c2', '248', 8, 'blk_taj_4779eb49169f58bb', 0, NULL, 'Marker: Qāmūs gloss. Reading: bolting.', 'high', 'active');
