INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شرط:khalil_kitab_ayn', 'شرط', '5d72ccb19d655d71cfab7075d4', 'الشَّرطُ: معروف في البيع، والفعل: شارطه فشرط له على كذا وكذا، يشرطُ له.', 'a condition, known in selling; to set terms', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_519f0d6cdd142b06', '2238', NULL, 'blk_kay_614a2f767d1e985c', 0, NULL, 'Marker: head gloss. Reading: condition.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شرط:ibn_durayd_jamharat_lugha', 'شرط', '5d72ccb19d655d71cfab7075d4', 'والشَّرَط: رَدِيء المَال من الْإِبِل وَالْغنم، وَالْجمع أَشْرَاط.', 'the poorest of one''s camels and sheep', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_bba2a268773c7a27', '540', NULL, 'blk_jam_a61c9c6c4dab03da', 0, NULL, 'Marker: head gloss. Reading: poor stock. Differs from the main reading (condition).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شرط:jawhari_sihah', 'شرط', '5d72ccb19d655d71cfab7075d4', 'الشَرْطُ معروفٌ، وكذلك الشَريطَةُ، والجمع شُروطٌ وشَرائِطُ. وقد شَرَطَ عليه كذا يَشْرِطُ ويَشْرُطُ، واشْتَرَطَ عليه.', 'condition, well known; to set a condition', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_d7c42588e66db549', '2253', 3, 'blk_sih_9b59539937f774a5', 0, NULL, 'Marker: head gloss. Reading: condition.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شرط:raghib_mufradat', 'شرط', '5d72ccb19d655d71cfab7075d4', 'الشَّرْطُ: كلّ حكم معلوم متعلّق بأمر يقع بوقوعه، وذلك الأمر كالعلامة له', 'a set term tied to a thing, like its sign', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_d62bb4345e6af8c4', '450', 1, 'blk_mfr_f42de6977da3cc80', 0, NULL, 'Marker: opening definition. Reading: condition. Primary: condition — 7 of 10 books (al-Khalīl blk_kay_614a2f767d1e985c; al-Jawharī blk_sih_9b59539937f774a5; al-Rāghib blk_mfr_f42de6977da3cc80; Lisān blk_lsn_363e27371a6d0da7; al-Qāmūs blk_qms_636d4adbd4e096a3; Tāj blk_taj_76ac40b7e757adf8; Lane blk_lane_8a9403db3c9eefff). Other readings: poor stock: Ibn Durayd · small cuts: al-Miṣbāḥ · mark: Ibn Fāris.', 'high', 'active');
