INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شرع:ibn_manzur_lisan_arab', 'شرع', 'fdabd972d0cbb3b3afdc81446f', 'شَرَعَ الوارِدُ يَشْرَعُ شَرْعاً وشُروعاً: تَنَاوَلَ الماءَ بفِيه.', 'the one at the water drank with his mouth', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_4d9ec99beed561b0', '507', 1, 'blk_lsn_be199b14b6775b82', 0, NULL, 'Marker: first definition. Reading: going down to water.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شرع:fayyumi_misbah_munir', 'شرع', 'fdabd972d0cbb3b3afdc81446f', 'الشِّرْعَةُ بِالْكَسْرِ الدِّينُ وَالشَّرْعُ وَالشَّرِيعَةُ مِثْلُهُ مَأْخُوذٌ مِنْ الشَّرِيعَةِ وَهِيَ مَوْرِدُ النَّاسِ لِلِاسْتِقَا', 'religion, named from the people''s watering place', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_44146662303c2868', '1586', NULL, 'blk_msb_5df843c9b19fc86c', 0, NULL, 'Marker: «مأخوذ من». Reading: watering place.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شرع:zabidi_taj_arus', 'شرع', 'fdabd972d0cbb3b3afdc81446f', 'أَصْلُ الشَّريعة فِي كَلَام العَرَبِ: مَورِدُ الشَّارِبَةِ الَّتِي يَشرَعُها النّاسُ، فيَشرَبونَ مِنْهَا ويَسْتَقونَ', 'at first: the place people go to drink', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_4ab3b8ae5e69379d', '260', 21, 'blk_taj_1b0244b8ed9b7b0c', 0, NULL, 'Marker: «أصل». Reading: watering place.', 'high', 'active');
