INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شرك:fayyumi_misbah_munir', 'شرك', '787435990abe677d16e34df2b2', 'شَرَكْتُهُ فِي الْأَمْرِ أَشْرَكُهُ مِنْ بَابِ تَعِبَ شَرِكًا وَشَرِكَةً وِزَانُ كَلِمٍ وَكَلِمَةٍ بِفَتْحِ الْأَوَّلِ وَكَسْرِ الثَّانِي إذَا صِرْتُ لَهُ شَرِيكًا', 'I became his partner in the matter', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_ce79864564de8fee', '1589', NULL, 'blk_msb_64ae4506c3a4e986', 0, NULL, 'Marker: head gloss. Reading: partnership.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شرك:qamus_muhit', 'شرك', '787435990abe677d16e34df2b2', 'الشِّرْكُ والشِّرْكَةُ، بكسرهما، وضَمِّ الثانبِمَعْنًى. وقد اشْتَرَكا وتَشارَكا، وشارَكَ أحدُهُما الآخَرَ.', 'partnership; the two shared', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_5702208faa096e5d', NULL, NULL, 'blk_qms_380ec6b0edbfa93e', 0, NULL, 'Marker: Qāmūs gloss. Reading: sharing.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شرك:zabidi_taj_arus', 'شرك', '787435990abe677d16e34df2b2', 'الشِّرْكُ والشِّرْكَةُ، بكسرِهِما وضمِّ الثانِي بمعنّى وَاد، وَهُوَ مُخالَطَةُ الشَّرِيكَيْنِ', 'partnership: two partners mixing', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_f61930145e44850d', '223', 27, 'blk_taj_377e5833f240fc38', 0, NULL, 'Marker: Qāmūs gloss. Reading: sharing.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شرك:lane_lexicon', 'شرك', '787435990abe677d16e34df2b2', 'He shared, participated, or partook, with him in it', 'he shared with him in it', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_ba6412ab6969b8b6', '1541', NULL, 'blk_lane_552695782bf458f0', 0, NULL, 'Marker: first sense A1. Reading: sharing.', 'high', 'active');
