INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:شطا:jawhari_sihah', 'شطا', '4c7ece7281d6635947ef237b1f', 'شطء الزرع والنبات: فراخه، والجمع: أشطاءُ.', 'a crop''s or plant''s young shoots', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_84a44584b20b38a0', '97', 1, 'blk_sih_7d7032484e52fd7c', 0, NULL, 'Marker: head gloss. Reading: shoots.', 'high', 'active');
